const express = require("express");

const app = express();
app.use(express.json());

let tarefas = [{ id: 1, titulo: "Primeira", feita: false }];
let proximoId = 2;

// listar
app.get("/api/tarefas", (req, res) => {
  res.json(tarefas);
});

// criar
app.post("/api/tarefas", (req, res) => {
  const titulo = req.body?.titulo;
  if (typeof titulo !== "string" || titulo.trim().length < 2) {
    return res.status(400).json({ erro: "titulo: texto de 2 caracteres ou mais" });
  }

  const tarefa = { id: proximoId++, titulo: titulo.trim(), feita: false };
  tarefas.push(tarefa);
  res.status(201).json(tarefa);
});

// alterar
app.put("/api/tarefas/:id", (req, res) => {
  const id = Number(req.params.id);
  const tarefa = tarefas.find((t) => t.id === id);
  if (!tarefa) return res.status(404).json({ erro: "não encontrada" });

  if (typeof req.body?.feita === "boolean") tarefa.feita = req.body.feita;
  res.json(tarefa);
});

// apagar
app.delete("/api/tarefas/:id", (req, res) => {
  const id = Number(req.params.id);
  const antes = tarefas.length;
  tarefas = tarefas.filter((t) => t.id !== id);

  if (tarefas.length === antes) return res.status(404).json({ erro: "não encontrada" });
  res.status(204).end();          // deu certo e não tem corpo pra devolver
});

app.listen(3000);

