const express = require("express");
const { DatabaseSync } = require("node:sqlite");

const app = express();
app.use(express.json());
app.use(express.static("public"));

const banco = new DatabaseSync("tarefas.db");
banco.exec(`CREATE TABLE IF NOT EXISTS tarefas (
  id INTEGER PRIMARY KEY,
  titulo TEXT NOT NULL,
  feita INTEGER NOT NULL DEFAULT 0
)`);

// o banco guarda 0 e 1; o JSON quer true e false
const emTarefa = (l) => ({ id: l.id, titulo: l.titulo, feita: Boolean(l.feita) });

app.get("/api/tarefas", (req, res) => {
  const linhas = banco.prepare("SELECT id, titulo, feita FROM tarefas ORDER BY id").all();
  res.json(linhas.map(emTarefa));
});

app.post("/api/tarefas", (req, res) => {
  const titulo = req.body?.titulo;
  if (typeof titulo !== "string" || titulo.trim().length < 2) {
    return res.status(400).json({ erro: "titulo: texto de 2 caracteres ou mais" });
  }

  // o ? é o espaço reservado: o valor viaja separado do comando
  const r = banco.prepare("INSERT INTO tarefas (titulo) VALUES (?)").run(titulo.trim());
  res.status(201).json({ id: Number(r.lastInsertRowid), titulo: titulo.trim(), feita: false });
});

app.put("/api/tarefas/:id", (req, res) => {
  const r = banco
    .prepare("UPDATE tarefas SET feita = ? WHERE id = ?")
    .run(req.body?.feita ? 1 : 0, Number(req.params.id));

  if (r.changes === 0) return res.status(404).json({ erro: "não encontrada" });
  res.json({ ok: true });
});

app.listen(3000);

