const express = require("express");
const { mkdirSync } = require("node:fs");
const { DatabaseSync } = require("node:sqlite");

const app = express();
app.use(express.json());
app.use(express.static("public"));

mkdirSync("dados", { recursive: true });              // o sqlite não cria a pasta
const banco = new DatabaseSync("dados/tarefas.db");   // fora da pasta pública
banco.exec(`CREATE TABLE IF NOT EXISTS tarefas (
  id INTEGER PRIMARY KEY, titulo TEXT NOT NULL, feita INTEGER NOT NULL DEFAULT 0)`);

const emTarefa = (l) => ({ id: l.id, titulo: l.titulo, feita: Boolean(l.feita) });

const consultas = {
  listar: banco.prepare("SELECT id, titulo, feita FROM tarefas ORDER BY id"),
  criar: banco.prepare("INSERT INTO tarefas (titulo) VALUES (?)"),
  marcar: banco.prepare("UPDATE tarefas SET feita = ? WHERE id = ?"),
  apagar: banco.prepare("DELETE FROM tarefas WHERE id = ?"),
};

app.get("/api/tarefas", (req, res) => res.json(consultas.listar.all().map(emTarefa)));

app.post("/api/tarefas", (req, res) => {
  const titulo = req.body?.titulo;
  if (typeof titulo !== "string" || titulo.trim().length < 2) {
    return res.status(400).json({ erro: "titulo: texto de 2 caracteres ou mais" });
  }
  const r = consultas.criar.run(titulo.trim());
  res.status(201).json({ id: Number(r.lastInsertRowid), titulo: titulo.trim(), feita: false });
});

app.put("/api/tarefas/:id", (req, res) => {
  const r = consultas.marcar.run(req.body?.feita ? 1 : 0, Number(req.params.id));
  if (r.changes === 0) return res.status(404).json({ erro: "não encontrada" });
  res.json({ ok: true });
});

app.delete("/api/tarefas/:id", (req, res) => {
  const r = consultas.apagar.run(Number(req.params.id));
  if (r.changes === 0) return res.status(404).json({ erro: "não encontrada" });
  res.status(204).end();
});

app.listen(process.env.PORT ?? 3000);

/*
  no Caderno: o arquivo ficou em dados/tarefas.db, ao lado do servidor.js,
  e NÃO dentro de public/. Se estivesse em public, qualquer pessoa baixaria
  o banco inteiro digitando o endereço dele.

  preparar as consultas uma vez, no topo, é mais rápido e deixa claro,
  num lugar só, tudo que a API faz com o banco.
*/
